const icon = n => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.box}</svg>`;

function page() {
  const nav = [
    ['Visão geral','dashboard','Dashboard'],['Gestão','box','Produtos'],['','truck','Fornecedores'],['','cart','Compras'],['','stock','Recebimentos'],['','stock','Estoque'],
    ['Operação','sale','Vendas'],['','wallet','Financeiro'],['','calc','Calculadora'],['Análise','report','Relatórios'],['Administração','settings','Configurações']
  ].map(([group,ic,label],i)=>`${group?`<p class="nav-group">${group}</p>`:''}<button class="nav-item ${i===0?'active':''}" data-page="${label}">${icon(ic)}<span>${label}</span>${label==='Estoque'?'<b>0</b>':''}</button>`).join('');
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NexCell ERP</title><meta name="description" content="Gestão interna NexCell"><style>${css}</style></head><body>
  <div class="shell"><aside id="sidebar"><div class="brand"><div class="nmark"><i></i><i></i></div><div class="wordmark"><strong>Nex<span>Cell</span></strong><small>GESTÃO</small></div></div><nav>${nav}</nav><div class="aside-foot"><div class="user"><span id="avatar">NC</span><div><strong id="userName">Carregando...</strong><small id="userRole">Sessão segura</small></div></div><a href="/signout-with-chatgpt?return_to=/" target="_top">Sair</a></div></aside>
  <main><header><button class="mobile" id="menu">${icon('menu')}</button><div><small>Operação NexCell</small><h1 id="title">Dashboard</h1></div><div class="header-actions"><label class="search">${icon('search')}<input id="search" placeholder="Buscar no sistema"><kbd>⌘ K</kbd></label><button class="round">${icon('bell')}<i></i></button><div class="profile"><span id="topAvatar">NC</span><div><strong id="topName">NexCell</strong><small id="topRole">Conta segura</small></div></div></div></header><section id="app">${dashboard()}</section></main></div>
  <div class="toast" id="toast" role="status"></div><script>${client}</script></body></html>`;
}

export { page };

function dashboard(){return `<div class="intro"><div><h2>Visão da operação</h2><p>Os indicadores serão preenchidos à medida que os módulos entrarem em operação.</p></div><span class="date">Outubro de 2026</span></div>
<div class="metrics"><article><span class="metric-icon blue">${icon('wallet')}</span><small>Faturamento do mês</small><strong>—</strong><p>Sem vendas registradas</p></article><article><span class="metric-icon cyan">${icon('report')}</span><small>Resultado estimado</small><strong>—</strong><p>Aguardando movimentações</p></article><article><span class="metric-icon violet">${icon('sale')}</span><small>Vendas realizadas</small><strong>0</strong><p>Nenhuma venda no período</p></article><article><span class="metric-icon amber">${icon('stock')}</span><small>Estoque crítico</small><strong>0</strong><p>Catálogo ainda vazio</p></article></div>
<div class="feature"><div class="feature-copy"><span>FUNDAÇÃO OPERACIONAL</span><h3>Pronto para organizar sua primeira entrada de estoque.</h3><p>Cadastre produtos e fornecedores na próxima fase. O painel passa a calcular os indicadores somente com dados persistidos.</p><button data-page="Produtos">Ver próximos módulos</button></div><div class="feature-chart"><div class="chart-head"><strong>Atividade operacional</strong><span>Últimos 7 dias</span></div><svg viewBox="0 0 700 190" preserveAspectRatio="none"><defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#0bc7fc" stop-opacity=".28"/><stop offset="1" stop-color="#0bc7fc" stop-opacity="0"/></linearGradient></defs><path d="M0 155 C85 150 85 125 150 135 S250 90 315 105 S410 55 480 78 S580 42 700 55 L700 190 L0 190Z" fill="url(#g)"/><path d="M0 155 C85 150 85 125 150 135 S250 90 315 105 S410 55 480 78 S580 42 700 55" fill="none" stroke="#0bc7fc" stroke-width="4"/><g fill="#0bc7fc"><circle cx="315" cy="105" r="5"/><circle cx="480" cy="78" r="5"/></g></svg><div class="axis"><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sáb</span><span>Dom</span></div></div></div>
<div class="lower"><article class="panel"><div class="panel-head"><div><h3>Primeiros passos</h3><p>Estrutura preparada para os fluxos comerciais.</p></div><span class="tag">Fase 1 concluída</span></div><ol class="steps"><li class="done"><i>✓</i><div><strong>Identidade e acesso</strong><p>Sessão privada gerenciada pelo Sites.</p></div></li><li class="done"><i>✓</i><div><strong>Base persistente</strong><p>D1 conectado com perfis, configurações e auditoria.</p></div></li><li><i>3</i><div><strong>Catálogo e fornecedores</strong><p>Próxima fase de implementação.</p></div></li></ol></article><article class="panel"><div class="panel-head"><div><h3>Alertas</h3><p>Itens que pedem atenção.</p></div></div><div class="empty"><span>${icon('bell')}</span><strong>Nenhum alerta agora</strong><p>Alertas aparecerão com dados reais de estoque, compras e vendas.</p></div></article></div>`}

const catalogCss=`.module-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.module-head h2{font-size:19px;margin:0 0 5px}.module-head p{font-size:10px;color:#718096;margin:0}.primary-action{border:0;border-radius:11px;background:linear-gradient(135deg,#0bc7fc,#0265f7);color:#fff;padding:11px 15px;font-size:10px;font-weight:700}.tools{background:#fff;border:1px solid #e7ecf3;border-bottom:0;border-radius:16px 16px 0 0;padding:13px;display:flex;gap:9px}.tools input,.tools select{height:38px;border:1px solid #e0e7ef;border-radius:10px;padding:0 11px;background:#fff;font-size:10px;outline:0}.tools input{min-width:240px}.data-table{background:#fff;border:1px solid #e7ecf3;border-radius:0 0 16px 16px;overflow:auto}.data-table table{width:100%;border-collapse:collapse;min-width:800px}.data-table th{text-align:left;background:#f9fbfd;color:#8a96a6;font-size:8px;letter-spacing:.05em;padding:11px 16px}.data-table td{border-top:1px solid #edf1f5;padding:13px 16px;font-size:10px}.data-table td strong{display:block;font-size:10px}.data-table td small{color:#929dac;font-size:8px}.money{font-variant-numeric:tabular-nums}.stock-pill,.state-pill{display:inline-flex;padding:4px 7px;border-radius:9px;font-size:8px;font-weight:700}.stock-pill{background:#eaf8ef;color:#16813d}.stock-pill.low{background:#fff3dd;color:#b46a00}.state-pill.off{background:#f1f3f6;color:#7e8998}.row-actions{display:flex;gap:5px}.row-actions button{border:1px solid #e2e8f0;background:#fff;border-radius:8px;padding:5px 7px;font-size:8px;color:#536174}.table-empty{text-align:center;padding:55px!important;color:#8a96a6}.drawer-shade{position:fixed;inset:0;background:rgba(7,29,51,.42);z-index:40;display:none}.drawer-shade.open{display:block}.drawer{position:absolute;right:0;top:0;height:100%;width:min(640px,100%);background:#fff;padding:27px;overflow:auto;box-shadow:-20px 0 50px rgba(7,29,51,.16)}.drawer-head{display:flex;justify-content:space-between;margin-bottom:22px}.drawer-head h2{font-size:18px;margin:0 0 5px}.drawer-head p{font-size:10px;color:#7e8998;margin:0}.drawer-close{border:0;background:#f2f5f8;border-radius:9px;width:34px;height:34px;color:#647184}.field select,.field textarea{width:100%;border:1px solid #dfe6ed;border-radius:11px;padding:11px 12px;outline:0;font-size:11px;background:#fff}.field textarea{min-height:80px;resize:vertical}.section-title{font-size:11px;margin:23px 0 10px;padding-top:17px;border-top:1px solid #e8edf3}.variant-row{display:grid;grid-template-columns:1.15fr 1fr .8fr .8fr 34px;gap:8px;margin-bottom:8px}.variant-row input{width:100%;height:38px;border:1px solid #dfe6ed;border-radius:9px;padding:0 9px;font-size:9px}.variant-row button{border:0;background:#feeeee;color:#dc2626;border-radius:8px}.secondary-action{border:1px solid #dfe6ed;background:#fff;color:#28749f;border-radius:9px;padding:8px 10px;font-size:9px;font-weight:700}.drawer-actions{position:sticky;bottom:-27px;margin:24px -27px -27px;padding:14px 27px;background:#fff;border-top:1px solid #e7ecf3;display:flex;justify-content:flex-end;gap:8px}.drawer-actions button{border-radius:10px;padding:10px 14px;font-size:10px;font-weight:700}.cancel{border:1px solid #dfe6ed;background:#fff;color:#637083}.confirm{border:0;background:linear-gradient(135deg,#0bc7fc,#0265f7);color:#fff}.loading-row{height:3px;background:linear-gradient(90deg,#0bc7fc,#0265f7);animation:load 1s infinite;transform-origin:left}@keyframes load{0%{transform:scaleX(.1)}50%{transform:scaleX(.8)}100%{transform:scaleX(.1)}}@media(max-width:700px){.module-head{align-items:start;gap:10px}.tools{overflow:auto}.tools input{min-width:190px}.drawer{padding:20px}.form-grid{grid-template-columns:1fr}.variant-row{grid-template-columns:1fr 1fr}.variant-row button{min-height:36px}.drawer-actions{margin:24px -20px -20px;bottom:-20px;padding:12px 20px}}`;
const baseCss=`@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Inter,sans-serif;color:#111827;background:#f6f8fb}button,input{font:inherit}button{cursor:pointer}.shell{min-height:100vh}aside{position:fixed;inset:0 auto 0 0;width:252px;background:#fff;border-right:1px solid #e7ecf3;display:flex;flex-direction:column;z-index:10}.brand{height:96px;display:flex;align-items:center;padding:0 30px;border-bottom:1px solid #edf1f5;gap:12px}.nmark{width:34px;height:38px;position:relative}.nmark i{position:absolute;left:2px;width:10px;height:34px;border-radius:8px 1px;background:linear-gradient(180deg,#09d0f5,#0265f7);transform:skew(-27deg)}.nmark i:last-child{left:18px;top:2px;height:30px;transform:skew(27deg)}.wordmark strong{font-size:21px}.wordmark strong span{color:#029cf9}.wordmark small{display:block;font-size:7px;letter-spacing:3px;color:#9ca3af}.nav-group{margin:20px 28px 7px;color:#a2adba;font-size:9px;font-weight:700}.nav-item{width:calc(100% - 28px);margin:2px 14px;padding:10px 14px;border:0;background:transparent;border-radius:11px;color:#637083;display:flex;align-items:center;gap:12px;text-align:left;font-size:12px;font-weight:600}.nav-item svg{width:18px}.nav-item span{flex:1}.nav-item b{background:#e8edf3;border-radius:12px;padding:2px 7px;font-size:9px}.nav-item:hover{background:#f4f8fb}.nav-item.active{color:#093662;background:#e5f8ff;box-shadow:inset 3px 0 #029cf9}.nav-item.active svg{color:#029cf9}.aside-foot{margin-top:auto;border-top:1px solid #edf1f5;padding:17px 20px;display:flex;align-items:center}.user,.profile{display:flex;align-items:center;gap:9px;min-width:0;flex:1}.user>span,.profile>span{width:35px;height:35px;border-radius:50%;background:linear-gradient(135deg,#0bc7fc,#0265f7);color:#fff;display:grid;place-items:center;font-size:10px;font-weight:800}.user strong,.profile strong{display:block;font-size:10px}.user small,.profile small{font-size:9px;color:#8a96a6}.aside-foot>a{font-size:10px;color:#6b7280;text-decoration:none}main{margin-left:252px;min-height:100vh}header{height:96px;padding:0 34px;background:#fff;border-bottom:1px solid #e7ecf3;display:flex;align-items:center;gap:18px;position:sticky;top:0;z-index:8}header>div:first-of-type{margin-right:auto}header small{color:#8a96a6;font-size:10px}h1{font-size:22px;margin:3px 0 0}.header-actions{display:flex;align-items:center;gap:11px}.search{width:260px;height:40px;border:1px solid #e2e8f0;border-radius:11px;display:flex;align-items:center;padding:0 11px;gap:8px}.search svg{width:16px}.search input{border:0;outline:0;flex:1;font-size:11px}.search kbd{background:#f2f5f8;padding:2px 5px;font-size:8px}.round{height:40px;width:40px;border-radius:11px;border:1px solid #e7ecf3;background:#fff;position:relative}.round svg{width:17px}.round i{position:absolute;width:6px;height:6px;border-radius:50%;background:#ef4444;top:8px;right:8px}.mobile{display:none;border:0;background:#eaf8ff;border-radius:9px;width:38px;height:38px;color:#0265f7}#app{padding:27px 34px 45px;max-width:1500px;margin:auto}.intro{display:flex;justify-content:space-between;align-items:end;margin-bottom:20px}.intro h2{font-size:19px;margin:0 0 5px}.intro p{font-size:11px;color:#718096;margin:0}.date{font-size:10px;padding:8px;border:1px solid #e1e8ef;background:#fff;border-radius:9px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.metrics article{background:#fff;border:1px solid #e7ecf3;min-height:150px;padding:19px;position:relative}.metrics article:first-child{border-radius:16px 0 0 16px}.metrics article:last-child{border-radius:0 16px 16px 0}.metric-icon{position:absolute;right:17px;top:17px;width:35px;height:35px;border-radius:50%;display:grid;place-items:center}.metric-icon svg{width:17px}.metric-icon.blue{background:#e5f3ff;color:#0265f7}.metric-icon.cyan{background:#defaff;color:#029cc9}.metric-icon.violet{background:#f0edff;color:#725ce9}.metric-icon.amber{background:#fff5df;color:#d78a00}.metrics small{color:#6b7280;font-size:10px}.metrics strong{display:block;font-size:28px;margin:25px 0 6px}.metrics p{font-size:9px;color:#9ca3af}.feature{margin-top:17px;background:#082842;color:#fff;border-radius:18px;display:grid;grid-template-columns:330px 1fr;overflow:hidden}.feature-copy{padding:29px}.feature-copy>span{font-size:8px;color:#65dfff}.feature-copy h3{font-size:22px;line-height:1.22}.feature-copy p{color:#9dc1d8;font-size:11px;line-height:1.65}.feature-copy button{border:0;border-radius:10px;padding:10px}.feature-chart{padding:28px;background:rgba(11,199,252,.06)}.chart-head,.axis{display:flex;justify-content:space-between;font-size:9px;color:#8eb4cc}.feature-chart svg{width:100%;height:180px}.lower{display:grid;grid-template-columns:1.2fr .8fr;gap:17px;margin-top:17px}.panel{background:#fff;border:1px solid #e7ecf3;border-radius:16px;padding:20px}.panel-head{display:flex;justify-content:space-between}.panel-head h3{font-size:13px;margin:0}.panel-head p{font-size:9px;color:#8a96a6}.tag{font-size:8px;color:#138443;background:#eaf8ef;padding:5px 8px;border-radius:10px}.steps{list-style:none;padding:0;display:grid;grid-template-columns:repeat(3,1fr)}.steps li{padding:8px;display:flex;gap:8px}.steps i{font-style:normal}.steps strong{font-size:10px}.steps p{font-size:8px;color:#8b97a7}.empty,.placeholder{text-align:center;padding:35px}.empty strong{display:block;font-size:10px}.empty p,.placeholder p{font-size:9px;color:#8b97a7}.placeholder{background:#fff;border:1px solid #e7ecf3;border-radius:16px}.settings-form{max-width:720px;background:#fff;border:1px solid #e7ecf3;border-radius:16px;padding:25px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.field label{display:block;font-size:9px;color:#657185;margin-bottom:6px}.field input{width:100%;height:42px;border:1px solid #dfe6ed;border-radius:11px;padding:0 12px;font-size:11px}.field.full{grid-column:1/-1}.save{margin-top:18px;border:0;border-radius:11px;background:#029cf9;color:#fff;padding:11px 16px}.toast{position:fixed;right:24px;bottom:24px;background:#082842;color:#fff;border-radius:11px;padding:12px 15px;font-size:10px;opacity:0;transform:translateY(12px);transition:.2s;z-index:60}.toast.show{opacity:1;transform:none}@media(max-width:1050px){.metrics{grid-template-columns:1fr 1fr}.search{display:none}.feature{grid-template-columns:300px 1fr}}@media(max-width:780px){aside{transform:translateX(-100%);transition:.2s}aside.open{transform:none}main{margin-left:0}header{height:78px;padding:0 18px}.mobile{display:grid;place-items:center}.profile div{display:none}#app{padding:20px}.feature,.lower{grid-template-columns:1fr}}@media(max-width:520px){.metrics{grid-template-columns:1fr}.metrics article{border-radius:14px!important}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}:focus-visible{outline:3px solid rgba(2,156,249,.3);outline-offset:2px}`;
const operationsCss=`.summary-strip{display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border:1px solid #e7ecf3;border-radius:16px;margin-bottom:16px}.summary-strip div{padding:17px;border-right:1px solid #edf1f5}.summary-strip div:last-child{border:0}.summary-strip small{display:block;color:#8a96a6;font-size:8px;margin-bottom:7px}.summary-strip strong{font-size:17px}.purchase-items{display:grid;gap:8px}.purchase-item{display:grid;grid-template-columns:1fr 90px 110px 34px;gap:8px}.purchase-item select,.purchase-item input{min-width:0;height:39px;border:1px solid #dfe6ed;border-radius:9px;padding:0 9px;font-size:9px;background:#fff}.purchase-item button{border:0;border-radius:8px;background:#feeeee;color:#dc2626}.receipt-line{display:grid;grid-template-columns:1fr 80px 80px;gap:8px;align-items:center;padding:10px 0;border-bottom:1px solid #edf1f5}.receipt-line strong{font-size:10px}.receipt-line small{display:block;color:#8a96a6;font-size:8px}.receipt-line input{height:38px;border:1px solid #dfe6ed;border-radius:9px;padding:0 8px;width:100%}.movement{font-size:8px;color:#647184}.movement b{color:#17283c}.state-draft{background:#f1f3f6;color:#687587}.state-partial{background:#fff4dd;color:#a76500}.state-paid,.state-received{background:#eaf8ef;color:#16813d}@media(max-width:700px){.summary-strip{grid-template-columns:1fr 1fr}.summary-strip div:nth-child(2){border-right:0}.purchase-item{grid-template-columns:1fr 1fr}.receipt-line{grid-template-columns:1fr 70px 70px}}`;
const css = baseCss + catalogCss + operationsCss;

const client = `const $=s=>document.querySelector(s);const app=$('#app'),title=$('#title');function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2500)}async function session(){const r=await fetch('/api/session');if(!r.ok)return;const {user}=await r.json();const n=user.full_name||user.email||'Usuário NexCell',initials=n.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();['#userName','#topName'].forEach(s=>$(s).textContent=n);['#userRole','#topRole'].forEach(s=>$(s).textContent=user.role);['#avatar','#topAvatar'].forEach(s=>$(s).textContent=initials)}function placeholder(name){return '<div class="placeholder"><span>${icon('box')}</span><h2>'+name+'</h2><p>Este módulo entra nas próximas fases. Ele não exibe dados fictícios e será liberado quando persistência, validações e regras de negócio estiverem concluídas.</p></div>'}function settings(){return '<form class="settings-form" id="settingsForm"><h2>Dados da empresa</h2><p>Configurações persistidas no servidor e protegidas por perfil.</p><div class="form-grid"><div class="field full"><label>Nome da empresa</label><input name="company" value="NexCell" required maxlength="80"></div><div class="field"><label>Estoque mínimo padrão</label><input name="minimum" type="number" min="0" value="5"></div><div class="field"><label>E-mail operacional</label><input name="email" type="email" placeholder="operacao@nexcell.com.br"></div></div><button class="save">Salvar configurações</button></form>'}function openPage(name){title.textContent=name;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===name));app.innerHTML=name==='Dashboard'?${JSON.stringify(dashboard())}:name==='Configurações'?settings():placeholder(name);$('#sidebar').classList.remove('open');if(name==='Configurações'){$('#settingsForm').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),r=await fetch('/api/settings',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({key:'company',value:{name:d.get('company'),minimum:Number(d.get('minimum')),email:d.get('email')}})});const out=await r.json();toast(r.ok?'Configurações salvas.':out.error)}}}document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)openPage(b.dataset.page)});$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}});session();`;

const catalogClient=`const esc=v=>String(v??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));const money=c=>(Number(c||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});function drawer(html){let d=document.querySelector('.drawer-shade');if(!d){d=document.createElement('div');d.className='drawer-shade';document.body.appendChild(d)}d.innerHTML='<div class="drawer">'+html+'</div>';d.classList.add('open');d.onclick=e=>{if(e.target===d||e.target.closest('[data-close]'))d.classList.remove('open')}}function loading(){app.insertAdjacentHTML('afterbegin','<div class="loading-row"></div>')}async function getJson(url){const r=await fetch(url),data=await r.json();if(!r.ok)throw new Error(data.error||'Falha ao carregar.');return data}function productShell(){return '<div class="module-head"><div><h2>Catálogo de produtos</h2><p>Produtos principais, variações, preços e saldo por SKU.</p></div><button class="primary-action" id="newProduct">+ Novo produto</button></div><div class="tools"><input id="productSearch" placeholder="Buscar nome ou SKU"><select id="categoryFilter"><option value="">Todas as categorias</option></select></div><div class="data-table"><table><thead><tr><th>Produto / SKU</th><th>Categoria</th><th>Fornecedor</th><th>Custo</th><th>Venda</th><th>Estoque</th><th>Ações</th></tr></thead><tbody id="productRows"><tr><td colspan="7" class="table-empty">Carregando catálogo...</td></tr></tbody></table></div>'}async function loadProducts(){const q=encodeURIComponent($('#productSearch')?.value||''),cat=encodeURIComponent($('#categoryFilter')?.value||'');try{const data=await getJson('/api/products?q='+q+'&category='+cat),body=$('#productRows');if(!body)return;body.innerHTML=data.items.length?data.items.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong><small>'+esc(x.sku||'Sem SKU')+(x.color?' · '+esc(x.color):'')+(x.compatible_model?' · '+esc(x.compatible_model):'')+'</small></td><td>'+esc(x.category_name||'—')+'</td><td>'+esc(x.supplier_name||'—')+'</td><td class="money">'+money(x.cost_cents)+'</td><td class="money">'+money(x.sale_price_cents)+'</td><td><span class="stock-pill '+(Number(x.physical)<=Number(x.minimum_stock)?'low':'')+'">'+Number(x.physical||0)+' un.</span></td><td><div class="row-actions"><button data-duplicate="'+x.id+'">Duplicar</button><button data-toggle-product="'+x.id+'" data-active="'+x.active+'">'+(x.active?'Inativar':'Ativar')+'</button></div></td></tr>').join(''):'<tr><td colspan="7" class="table-empty">Nenhum produto cadastrado. Use “Novo produto” para começar.</td></tr>'}catch(e){$('#productRows').innerHTML='<tr><td colspan="7" class="table-empty">'+esc(e.message)+'</td></tr>'}}async function setupProducts(){app.innerHTML=productShell();const cats=await getJson('/api/categories').catch(()=>({items:[]})),sup=await getJson('/api/suppliers').catch(()=>({items:[]}));cats.items.forEach(x=>$('#categoryFilter').insertAdjacentHTML('beforeend','<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>'));$('#productSearch').oninput=()=>{clearTimeout(window.pst);window.pst=setTimeout(loadProducts,250)};$('#categoryFilter').onchange=loadProducts;$('#newProduct').onclick=()=>productForm(cats.items,sup.items);loadProducts()}function variantRow(){return '<div class="variant-row"><input name="sku" placeholder="SKU *" required><input name="model" placeholder="Modelo compatível"><input name="color" placeholder="Cor"><input name="cost" type="number" min="0" step="0.01" placeholder="Custo *" required><button type="button" data-remove-variant>×</button><input name="price" type="number" min="0" step="0.01" placeholder="Preço *" required><input name="opening" type="number" min="0" step="1" placeholder="Estoque inicial"><input name="minimum" type="number" min="0" step="1" placeholder="Mínimo"><input name="barcode" placeholder="Código de barras"></div>'}function productForm(cats,sups){drawer('<div class="drawer-head"><div><h2>Novo produto</h2><p>Cadastre o produto e pelo menos uma variação vendável.</p></div><button class="drawer-close" data-close>×</button></div><form id="productForm"><div class="form-grid"><div class="field full"><label>Nome</label><input name="name" required maxlength="160"></div><div class="field"><label>Categoria</label><select name="categoryId"><option value="">Selecione</option>'+cats.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join('')+'</select></div><div class="field"><label>Marca</label><input name="brand" maxlength="80"></div><div class="field full"><label>Fornecedor</label><select name="supplierId"><option value="">Sem fornecedor</option>'+sups.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join('')+'</select></div><div class="field full"><label>Descrição</label><textarea name="description"></textarea></div><div class="field full"><label>Foto (JPG, PNG ou WebP; até 4 MB)</label><input name="image" type="file" accept="image/jpeg,image/png,image/webp"></div></div><h3 class="section-title">Variações e SKUs</h3><div id="variants">'+variantRow()+'</div><button type="button" class="secondary-action" id="addVariant">+ Adicionar variação</button><div class="drawer-actions"><button type="button" class="cancel" data-close>Cancelar</button><button class="confirm">Salvar produto</button></div></form>');$('#addVariant').onclick=()=>$('#variants').insertAdjacentHTML('beforeend',variantRow());$('#productForm').onclick=e=>{if(e.target.matches('[data-remove-variant]')&&document.querySelectorAll('.variant-row').length>1)e.target.closest('.variant-row').remove()};$('#productForm').onsubmit=saveProduct}async function saveProduct(e){e.preventDefault();const f=e.currentTarget,d=new FormData(f),variants=[...f.querySelectorAll('.variant-row')].map(r=>({sku:r.querySelector('[name=sku]').value,model:r.querySelector('[name=model]').value,color:r.querySelector('[name=color]').value,cost:r.querySelector('[name=cost]').value,price:r.querySelector('[name=price]').value,openingStock:r.querySelector('[name=opening]').value,minimumStock:r.querySelector('[name=minimum]').value,barcode:r.querySelector('[name=barcode]').value})),payload={name:d.get('name'),categoryId:d.get('categoryId'),brand:d.get('brand'),supplierId:d.get('supplierId'),description:d.get('description'),variants};const btn=f.querySelector('.confirm');btn.disabled=true;btn.textContent='Salvando...';const r=await fetch('/api/products',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),out=await r.json();if(!r.ok){toast(out.error);btn.disabled=false;btn.textContent='Salvar produto';return}const file=d.get('image');if(file&&file.size)await fetch('/api/products/'+out.id+'/image',{method:'PUT',headers:{'content-type':file.type},body:file});document.querySelector('.drawer-shade').classList.remove('open');toast('Produto cadastrado.');loadProducts()}function supplierShell(){return '<div class="module-head"><div><h2>Rede de fornecedores</h2><p>Contatos, prazos e produtos vinculados.</p></div><button class="primary-action" id="newSupplier">+ Novo fornecedor</button></div><div class="tools"><input id="supplierSearch" placeholder="Buscar nome ou e-mail"></div><div class="data-table"><table><thead><tr><th>Fornecedor</th><th>Contato</th><th>Localização</th><th>Prazo médio</th><th>Produtos</th><th>Situação</th><th>Ações</th></tr></thead><tbody id="supplierRows"><tr><td colspan="7" class="table-empty">Carregando fornecedores...</td></tr></tbody></table></div>'}async function loadSuppliers(){try{const data=await getJson('/api/suppliers?q='+encodeURIComponent($('#supplierSearch')?.value||''));$('#supplierRows').innerHTML=data.items.length?data.items.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong><small>'+esc(x.email||'Sem e-mail')+'</small></td><td>'+esc(x.whatsapp||x.phone||'—')+'</td><td>'+esc([x.city,x.state].filter(Boolean).join(' / ')||'—')+'</td><td>'+Number(x.lead_time_days||0)+' dias</td><td>'+Number(x.product_count||0)+'</td><td><span class="state-pill '+(x.active?'':'off')+'">'+(x.active?'Ativo':'Inativo')+'</span></td><td><div class="row-actions"><button data-toggle-supplier="'+x.id+'" data-active="'+x.active+'">'+(x.active?'Inativar':'Ativar')+'</button></div></td></tr>').join(''):'<tr><td colspan="7" class="table-empty">Nenhum fornecedor cadastrado. Use “Novo fornecedor” para começar.</td></tr>'}catch(e){$('#supplierRows').innerHTML='<tr><td colspan="7" class="table-empty">'+esc(e.message)+'</td></tr>'}}function setupSuppliers(){app.innerHTML=supplierShell();$('#newSupplier').onclick=supplierForm;$('#supplierSearch').oninput=()=>{clearTimeout(window.sst);window.sst=setTimeout(loadSuppliers,250)};loadSuppliers()}function supplierForm(){drawer('<div class="drawer-head"><div><h2>Novo fornecedor</h2><p>Informações comerciais e prazo de entrega.</p></div><button class="drawer-close" data-close>×</button></div><form id="supplierForm"><div class="form-grid"><div class="field full"><label>Nome</label><input name="name" required></div><div class="field"><label>Telefone</label><input name="phone"></div><div class="field"><label>WhatsApp</label><input name="whatsapp"></div><div class="field full"><label>E-mail</label><input name="email" type="email"></div><div class="field"><label>Cidade</label><input name="city"></div><div class="field"><label>Estado</label><input name="state" maxlength="2"></div><div class="field"><label>Prazo médio (dias)</label><input name="leadTime" type="number" min="0" value="0"></div><div class="field full"><label>Observações</label><textarea name="notes"></textarea></div></div><div class="drawer-actions"><button type="button" class="cancel" data-close>Cancelar</button><button class="confirm">Salvar fornecedor</button></div></form>');$('#supplierForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget)),r=await fetch('/api/suppliers',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(d)}),out=await r.json();if(!r.ok)return toast(out.error);document.querySelector('.drawer-shade').classList.remove('open');toast('Fornecedor cadastrado.');loadSuppliers()}}const originalOpenPage=openPage;openPage=function(name){title.textContent=name;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===name));$('#sidebar').classList.remove('open');if(name==='Produtos')return setupProducts();if(name==='Fornecedores')return setupSuppliers();return originalOpenPage(name)};document.addEventListener('click',async e=>{const dup=e.target.closest('[data-duplicate]');if(dup){const r=await fetch('/api/products/'+dup.dataset.duplicate+'/duplicate',{method:'POST'}),o=await r.json();toast(r.ok?'Produto duplicado.':o.error);if(r.ok)loadProducts()}const tp=e.target.closest('[data-toggle-product]');if(tp){const active=tp.dataset.active!=='1',r=await fetch('/api/products/'+tp.dataset.toggleProduct,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({active})}),o=await r.json();toast(r.ok?'Produto atualizado.':o.error);if(r.ok)loadProducts()}const ts=e.target.closest('[data-toggle-supplier]');if(ts){const active=ts.dataset.active!=='1',r=await fetch('/api/suppliers/'+ts.dataset.toggleSupplier,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({active})}),o=await r.json();toast(r.ok?'Fornecedor atualizado.':o.error);if(r.ok)loadSuppliers()}});`;

function enhancedPage(){return page().replace("</script>",catalogClient+"</script>")}
