const operationsClient=`function purchaseShell(){return '<div class="module-head"><div><h2>Pedidos de compra</h2><p>Pedido, pagamento e recebimento são acompanhados separadamente.</p></div><button class="primary-action" id="newPurchase">+ Nova compra</button></div><div class="data-table" style="border-radius:16px"><table><thead><tr><th>Compra</th><th>Fornecedor</th><th>Total</th><th>Pagamento</th><th>Recebimento</th><th>Ações</th></tr></thead><tbody id="purchaseRows"><tr><td colspan="6" class="table-empty">Carregando compras...</td></tr></tbody></table></div>'}async function loadPurchases(){try{const d=await getJson('/api/purchases');window.purchaseData=d.items;$('#purchaseRows').innerHTML=d.items.length?d.items.map(x=>'<tr><td><strong>'+esc(x.number)+'</strong><small>'+esc(x.order_date)+'</small></td><td>'+esc(x.supplier_name)+'</td><td class="money">'+money(x.total_cents)+'</td><td><span class="state-pill state-'+x.payment_status+'">'+({pending:'Pendente',partial:'Parcial',paid:'Pago'}[x.payment_status])+'</span><small>'+money(x.paid_cents)+' pago</small></td><td><span class="state-pill state-'+x.receipt_status+'">'+({pending:'Pendente',partial:'Parcial',received:'Recebido'}[x.receipt_status])+'</span></td><td><div class="row-actions">'+(x.payment_status!=='paid'?'<button data-pay="'+x.id+'" data-balance="'+(x.total_cents-x.paid_cents)+'">Pagar</button>':'')+(x.receipt_status!=='received'?'<button data-receive="'+x.id+'">Receber</button>':'')+'</div></td></tr>').join(''):'<tr><td colspan="6" class="table-empty">Nenhuma compra registrada.</td></tr>'}catch(e){$('#purchaseRows').innerHTML='<tr><td colspan="6" class="table-empty">'+esc(e.message)+'</td></tr>'}}async function setupPurchases(){app.innerHTML=purchaseShell();$('#newPurchase').onclick=purchaseForm;loadPurchases()}async function purchaseForm(){const [sup,products]=await Promise.all([getJson('/api/suppliers'),getJson('/api/products')]);const variants=products.items.filter((x,i,a)=>x.variant_id&&a.findIndex(y=>y.variant_id===x.variant_id)===i);const options=variants.map(x=>'<option value="'+x.variant_id+'" data-cost="'+(x.cost_cents/100)+'">'+esc(x.name)+' · '+esc(x.sku)+'</option>').join('');const item=()=>'<div class="purchase-item"><select name="variant"><option value="">Selecione o SKU</option>'+options+'</select><input name="quantity" type="number" min="1" placeholder="Qtd."><input name="cost" type="number" min="0" step="0.01" placeholder="Custo unit."><button type="button" data-remove-item>×</button></div>';drawer('<div class="drawer-head"><div><h2>Nova compra</h2><p>O pedido não altera o estoque até o recebimento.</p></div><button class="drawer-close" data-close>×</button></div><form id="purchaseForm"><div class="form-grid"><div class="field full"><label>Fornecedor</label><select name="supplierId" required><option value="">Selecione</option>'+sup.items.filter(x=>x.active).map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('')+'</select></div><div class="field"><label>Data</label><input name="orderDate" type="date" required value="'+new Date().toISOString().slice(0,10)+'"></div><div class="field"><label>Previsão</label><input name="expectedDate" type="date"></div></div><h3 class="section-title">Itens</h3><div id="purchaseItems" class="purchase-items">'+item()+'</div><button type="button" class="secondary-action" id="addPurchaseItem">+ Adicionar item</button><h3 class="section-title">Totais adicionais</h3><div class="form-grid"><div class="field"><label>Frete</label><input name="freight" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Desconto</label><input name="discount" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Outros custos</label><input name="otherCosts" type="number" min="0" step="0.01" value="0"></div><div class="field full"><label>Observações</label><textarea name="notes"></textarea></div></div><div class="drawer-actions"><button type="button" class="cancel" data-close>Cancelar</button><button class="confirm">Confirmar compra</button></div></form>');$('#addPurchaseItem').onclick=()=>$('#purchaseItems').insertAdjacentHTML('beforeend',item());$('#purchaseForm').onchange=e=>{if(e.target.name==='variant'){const o=e.target.selectedOptions[0],row=e.target.closest('.purchase-item');if(o?.dataset.cost)row.querySelector('[name=cost]').value=o.dataset.cost}};$('#purchaseForm').onclick=e=>{if(e.target.matches('[data-remove-item]')&&document.querySelectorAll('.purchase-item').length>1)e.target.closest('.purchase-item').remove()};$('#purchaseForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=new FormData(f),items=[...f.querySelectorAll('.purchase-item')].map(r=>({variantId:r.querySelector('[name=variant]').value,quantity:r.querySelector('[name=quantity]').value,unitCost:r.querySelector('[name=cost]').value})),payload={supplierId:d.get('supplierId'),orderDate:d.get('orderDate'),expectedDate:d.get('expectedDate'),freight:d.get('freight'),discount:d.get('discount'),otherCosts:d.get('otherCosts'),notes:d.get('notes'),items},r=await fetch('/api/purchases',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),o=await r.json();if(!r.ok)return toast(o.error);document.querySelector('.drawer-shade').classList.remove('open');toast('Compra '+o.number+' criada sem alterar o estoque.');loadPurchases()}}async function paymentForm(id,balance){const value=(Number(balance)/100).toFixed(2);drawer('<div class="drawer-head"><div><h2>Registrar pagamento</h2><p>Saldo da compra: '+money(balance)+'</p></div><button class="drawer-close" data-close>×</button></div><form id="paymentForm"><div class="form-grid"><div class="field"><label>Valor</label><input name="amount" type="number" min="0.01" step="0.01" value="'+value+'" required></div><div class="field"><label>Data</label><input name="date" type="date" value="'+new Date().toISOString().slice(0,10)+'" required></div><div class="field full"><label>Forma</label><select name="method"><option>PIX</option><option>Boleto</option><option>Cartão</option><option>Transferência</option></select></div></div><div class="drawer-actions"><button type="button" class="cancel" data-close>Cancelar</button><button class="confirm">Registrar pagamento</button></div></form>');$('#paymentForm').onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget)),r=await fetch('/api/purchases/'+id+'/payments',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),o=await r.json();if(!r.ok)return toast(o.error);document.querySelector('.drawer-shade').classList.remove('open');toast('Pagamento registrado.');loadPurchases()}}async function receiptForm(id){const d=await getJson('/api/purchases/'+id+'/items'),pending=d.items.filter(x=>x.received_quantity<x.quantity);drawer('<div class="drawer-head"><div><h2>Conferir recebimento</h2><p>Informe o recebido e as unidades avariadas.</p></div><button class="drawer-close" data-close>×</button></div><form id="receiptForm">'+pending.map(x=>'<div class="receipt-line" data-item="'+x.id+'"><div><strong>'+esc(x.product_name)+' · '+esc(x.sku)+'</strong><small>Pedido: '+x.quantity+' · já recebido: '+x.received_quantity+' · pendente: '+(x.quantity-x.received_quantity)+'</small></div><input name="received" type="number" min="0" max="'+(x.quantity-x.received_quantity)+'" placeholder="Recebido"><input name="damaged" type="number" min="0" placeholder="Avariado"></div>').join('')+'<div class="field full" style="margin-top:16px"><label>Observações</label><textarea name="notes"></textarea></div><div class="drawer-actions"><button type="button" class="cancel" data-close>Cancelar</button><button class="confirm">Confirmar entrada</button></div></form>');$('#receiptForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,items=[...f.querySelectorAll('.receipt-line')].map(r=>({itemId:r.dataset.item,received:r.querySelector('[name=received]').value,damaged:r.querySelector('[name=damaged]').value||0})).filter(x=>Number(x.received)>0),payload={idempotencyKey:crypto.randomUUID(),date:new Date().toISOString().slice(0,10),notes:new FormData(f).get('notes'),items},r=await fetch('/api/purchases/'+id+'/receipts',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),o=await r.json();if(!r.ok)return toast(o.error);document.querySelector('.drawer-shade').classList.remove('open');toast('Recebimento confirmado e estoque atualizado.');loadPurchases()}}function setupReceipts(){app.innerHTML=purchaseShell().replace('Pedidos de compra','Recebimentos pendentes').replace('Pedido, pagamento e recebimento são acompanhados separadamente.','Confira mercadorias antes de autorizar a entrada no estoque.').replace('<button class="primary-action" id="newPurchase">+ Nova compra</button>','');loadPurchases()}async function setupInventory(){app.innerHTML='<div class="module-head"><div><h2>Posição de estoque</h2><p>Físico, reservado e disponível por SKU.</p></div></div><div class="summary-strip" id="stockSummary"></div><div class="data-table" style="border-radius:16px"><table><thead><tr><th>Produto / SKU</th><th>Físico</th><th>Reservado</th><th>Disponível</th><th>Mínimo</th><th>Valor a custo</th></tr></thead><tbody id="stockRows"></tbody></table></div><div class="panel" style="margin-top:16px"><div class="panel-head"><div><h3>Movimentações recentes</h3><p>Histórico imutável de entradas e saídas.</p></div></div><div id="movements"></div></div>';try{const [d,m]=await Promise.all([getJson('/api/inventory'),getJson('/api/inventory/movements')]),physical=d.items.reduce((n,x)=>n+Number(x.physical),0),reserved=d.items.reduce((n,x)=>n+Number(x.reserved),0),available=physical-reserved,value=d.items.reduce((n,x)=>n+Number(x.physical)*Number(x.cost_cents),0);$('#stockSummary').innerHTML='<div><small>Estoque físico</small><strong>'+physical+'</strong></div><div><small>Reservado</small><strong>'+reserved+'</strong></div><div><small>Disponível</small><strong>'+available+'</strong></div><div><small>Valor a custo</small><strong>'+money(value)+'</strong></div>';$('#stockRows').innerHTML=d.items.length?d.items.map(x=>'<tr><td><strong>'+esc(x.product_name)+'</strong><small>'+esc(x.sku)+'</small></td><td>'+x.physical+'</td><td>'+x.reserved+'</td><td><span class="stock-pill '+(x.available<=x.minimum_stock?'low':'')+'">'+x.available+'</span></td><td>'+x.minimum_stock+'</td><td>'+money(x.physical*x.cost_cents)+'</td></tr>').join(''):'<tr><td colspan="6" class="table-empty">Nenhum saldo cadastrado.</td></tr>';$('#movements').innerHTML=m.items.length?m.items.map(x=>'<div class="receipt-line"><div><strong>'+esc(x.product_name)+' · '+esc(x.sku)+'</strong><small>'+esc(x.reason)+' · '+esc(x.actor_name)+'</small></div><span class="movement"><b>'+(x.quantity>0?'+':'')+x.quantity+'</b></span><span class="movement">Saldo '+x.physical_after+'</span></div>').join(''):'<div class="empty"><p>Nenhuma movimentação registrada.</p></div>'}catch(e){toast(e.message)}}const phase2Open=openPage;openPage=function(name){if(name==='Compras'){title.textContent=name;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===name));return setupPurchases()}if(name==='Recebimentos'){title.textContent=name;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===name));return setupReceipts()}if(name==='Estoque'){title.textContent=name;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===name));return setupInventory()}return phase2Open(name)};document.addEventListener('click',e=>{const pay=e.target.closest('[data-pay]');if(pay)paymentForm(pay.dataset.pay,pay.dataset.balance);const rec=e.target.closest('[data-receive]');if(rec)receiptForm(rec.dataset.receive)});`;
function phase3Page(){return enhancedPage().replace("</script>",operationsClient+"</script>")}
export { phase3Page };

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    try {
      if (url.pathname.startsWith("/api/")) return await api(request, env, url);
      if (url.pathname.startsWith("/images/")) { const object=await env.BUCKET.get(url.pathname.slice(8)); if(!object)return new Response("Não encontrado",{status:404}); return new Response(object.body,{headers:{"content-type":object.httpMetadata?.contentType||"application/octet-stream","cache-control":"private, max-age=3600"}}); }
      if (url.pathname === "/" || url.pathname === "/index.html") return new Response(phase3Page(), { headers:{"content-type":"text/html; charset=utf-8","cache-control":"private, no-store","content-security-policy":"default-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; script-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; frame-ancestors 'self' https://chatgpt.com"} });
      return new Response("Não encontrado", {status:404});
    } catch (error) {
      return url.pathname.startsWith("/api/") ? json({error:"Falha interna. Tente novamente."},500) : new Response("Falha interna",{status:500});
    }
  }
};
